# Take each mod 41
mods = [n % 41 for n in nums]
print("Mods:", mods)

# Find modular inverse of each mod 41
def modinv(a, m):
    # Extended Euclidean
    for x in range(1, m):
        if (a * x) % m == 1:
            return x
    return None

invs = [modinv(m, 41) for m in mods]
print("Inverses:", invs)

# Convert to characters (0-40 range, maybe A-Z + some)
# Let's try: 0=A, 1=B, ... 25=Z, 26=space, 27-40=?
# Or maybe 1-26 = A-Z, 0 = space
chars = []
for i in invs:
    if i == 0:
        chars.append(' ')
    elif 1 <= i <= 26:
        chars.append(chr(ord('A') + i - 1))
    else:
        chars.append(f'[{i}]')
print("Chars:", ''.join(chars))

# Try another mapping: 0-25 = A-Z, 26 = space
chars2 = []
for i in invs:
    if i <= 25:
        chars2.append(chr(ord('A') + i))
    elif i == 26:
        chars2.append(' ')
    else:
        chars2.append(f'[{i}]')
print("Chars2:", ''.join(chars2))"}
